  const now = Date.now();
  const canonical = topic => {
    const parts = String(topic).split('/');
    if (parts.length !== 3) return String(topic).toLowerCase();
    if (/^(?:0x[0-9a-f]+|\d+)$/i.test(parts[1])) parts[1] = BigInt(parts[1]).toString();
    return parts.join('/').toLowerCase();
  };
  let state = context.get('meters');
  if (!state) {
    state = { epoch: 0, online: null, inventory: 'Waiting for meter list', lastList: 0,
      listPending: 0, listToken: 0, queue: [], rows: {} };
    for (const spec of METERS) state.rows[spec.topic] = {
      ...spec, raw: null, value: null, watts: null, seen: 0, meterId: null,
      radioUnit: '', subscription: 'Not requested', pending: 0
    };
  }
  const requests = [];
  const diagnostics = [];
  const success = value => value !== null && value !== undefined && Number(value) === 0;
  function report(topic, detail) { diagnostics.push({ topic, payload: detail }); }
  if (String(msg.topic).startsWith('connection/')) {
    state.epoch++;
    state.queue = [];
    state.listPending = 0;
    state.lastList = 0;
    state.online = msg.payload === 'connected';
    state.inventory = state.online ? 'Refreshing meter list' : 'Radio disconnected / connecting';
    for (const row of Object.values(state.rows)) {
      row.subscription = state.online ? 'Not requested' : 'Disconnected';
      row.pending = 0;
      row.seen = 0;
      row.raw = row.value = row.watts = null;
    }
  } else if (msg._auRequest) {
    if (msg._auEpoch !== state.epoch) return null;
    if (msg._auRequest === 'list') {
      if (msg._auToken !== state.listToken) return null;
      state.listPending = 0;
      if (!success(msg.status_code) || !msg.payload || typeof msg.payload !== 'object' || Array.isArray(msg.payload)) {
        state.inventory = 'Meter list failed: ' + String(msg.status_code ?? 'invalid response');
        report('inventory', { status: msg.status_code, response: msg.payload });
      } else {
        state.online = true;
        state.inventory = 'Meter list received';
        const lookup = new Map();
        for (const [meterId, meta] of Object.entries(msg.payload)) {
          if (!/^\d+$/.test(meterId) || !meta || typeof meta !== 'object') continue;
          const topic = [meta.src, meta.num, meta.nam].join('/');
          lookup.set(canonical(topic), { meterId, meta });
        }
        for (const spec of METERS) {
          const row = state.rows[spec.topic];
          const match = lookup.get(canonical(spec.topic));
          if (!match) {
            if (row.subscription !== 'Not in meter list') report(spec.topic, 'Not in meter list');
            row.subscription = 'Not in meter list';
            row.meterId = null;
            row.pending = 0;
            row.seen = 0;
            row.raw = row.value = row.watts = null;
            continue;
          }
          row.radioUnit = typeof match.meta.unit === 'string' ? match.meta.unit : '';
          if (row.meterId !== match.meterId || !['Subscribed', 'Queued', 'Awaiting acknowledgement'].includes(row.subscription)) {
            if (row.meterId !== match.meterId) {
              row.seen = 0;
              row.raw = row.value = row.watts = null;
            }
            row.meterId = match.meterId;
            row.subscription = 'Queued';
            row.pending = 0;
            state.queue.push(spec.topic);
          }
        }
      }
    } else if (msg._auRequest === 'subscribe') {
      const row = state.rows[msg._auTopic];
      if (row && row.meterId === msg._auMeter && msg._auToken === row.pending) {
        row.pending = 0;
        row.subscription = success(msg.status_code) ? 'Subscribed' : 'Rejected: ' + String(msg.status_code);
        if (!success(msg.status_code)) report(row.topic, { status: msg.status_code, response: msg.payload });
      }
    }
  } else if (msg.topic !== '__tick') {
    const meta = msg.payload;
    const spec = METERS.find(m => canonical(m.topic) === canonical(msg.topic));
    if (spec && meta && typeof meta === 'object') {
      const row = state.rows[spec.topic];
      const raw = meta.value;
      if ((typeof raw === 'number' || (typeof raw === 'string' && raw.trim() !== '')) && Number.isFinite(Number(raw))) {
        row.raw = raw; // Already scaled by flexradio-js; preserve its exact sample.
        row.radioUnit = typeof meta.unit === 'string' ? meta.unit : row.radioUnit;
        row.value = Number(raw);
        if (spec.unit === '°C' && row.radioUnit.toLowerCase() === 'degf') row.value = (row.value - 32) * 5 / 9;
        row.watts = spec.power && (!row.radioUnit || row.radioUnit.toLowerCase() === 'dbm')
          ? 10 ** ((Number(raw) - 30) / 10) : null;
        row.seen = now;
        state.online = true;
      }
    }
  }
  if (msg.topic === '__tick') {
    if (state.listPending && now - state.listPending > 15000) {
      state.listPending = 0;
      state.inventory = 'Meter list timeout / radio unavailable';
      report('inventory', state.inventory);
    }
    for (const row of Object.values(state.rows)) {
      if (row.pending && now - row.pending > 15000) {
        row.pending = 0;
        row.subscription = 'Acknowledgement timeout';
        report(row.topic, row.subscription);
      }
    }
    const retryDelay = state.inventory === 'Meter list received' ? 60000 : 15000;
    if (!state.listPending && (!state.lastList || now - state.lastList >= retryDelay)) {
      state.lastList = now;
      state.listPending = now;
      state.listToken++;
      requests.push({ payload: 'meter list', _auRequest: 'list', _auEpoch: state.epoch, _auToken: state.listToken });
    }
    for (let n = 0; n < 5 && state.queue.length; n++) {
      const row = state.rows[state.queue.shift()];
      if (!row || row.subscription !== 'Queued' || !/^\d+$/.test(row.meterId)) continue;
      row.subscription = 'Awaiting acknowledgement';
      row.pending = now;
      requests.push({ payload: 'sub meter ' + row.meterId, _auRequest: 'subscribe',
        _auEpoch: state.epoch, _auToken: now, _auTopic: row.topic, _auMeter: row.meterId });
    }
  }
  // Full snapshots once per second keep new browser clients and stale states accurate.
  const publish = msg.topic === '__tick';
  const output = [requests.length ? requests : null];
  for (const section of ['pa', 'tx', 'rx', 'external']) {
    output.push(publish ? { payload: {
      section, online: state.online, inventory: state.inventory, timestamp: now,
      rows: Object.values(state.rows).filter(row => row.section === section).map(row => ({ ...row }))
    } } : null);
  }
  output.push(diagnostics.length ? diagnostics : null);
  context.set('meters', state);
  if (publish) {
    const received = Object.values(state.rows).filter(r => r.seen && now - r.seen < 15000).length;
    node.status({ fill: received === 35 ? 'green' : 'yellow', shape: 'dot', text: received + '/35 recent samples' });
  }
  return output;
